-- 029 - Banco visual de ejercicios Imperial Fitness
-- IMPORTANTE: esta semilla es opcional si usas el catálogo estático del frontend.
-- Ejecutar solo si tu tabla public.exercises usa id tipo varchar/text según las migraciones 011/013.

create index if not exists idx_exercises_segment_primary_muscle on public.exercises(segment, primary_muscle);
create index if not exists idx_exercises_active_segment on public.exercises(is_active, segment);

on conflict (id) do update set
  name = excluded.name,
  segment = excluded.segment,
  movement = excluded.movement,
  primary_muscle = excluded.primary_muscle,
  muscle_groups_json = excluded.muscle_groups_json,
  equipment = excluded.equipment,
  image_url = excluded.image_url,
  level = excluded.level,
  is_active = 1,
  needs_image_review = 0,
  coaching_notes = excluded.coaching_notes,
  updated_at = now();
